/**
 * Read-only availability + latency canary for the Maze Game Platform (task 9.2, D8).
 *
 * This canary is the always-on **read-only** probe of the shared backend. It runs every
 * 5 minutes (schedule set in the CDK construct, `infra/observability.ts`) and does exactly
 * two unauthenticated HTTP checks — it holds no credentials and never writes:
 *
 *  1. **Public leaderboard (primary availability + latency signal, R6.4/R6.5).** A GET of
 *     the public `GET /leaderboard?<mazeParams>` must return 200 with a well-formed body
 *     (`{ standings: [...] }`). This is the signal the leaderboard-latency alarm watches via
 *     the canary `Duration` metric, and the availability alarm watches via `SuccessPercent`.
 *  2. **Health liveness.** `GET /health` is JWT-protected, so an unauthenticated probe
 *     asserts the API is reachable and *rejects* the tokenless request with 401 (liveness).
 *     A 5xx or a network error there means the edge itself is down, which fails the run.
 *     We deliberately do NOT bake a token into this read-only canary.
 *
 * Configuration is injected as canary environment variables by the CDK construct — no URL,
 * secret, or PII is committed here (R11.4):
 *  - `MAZE_API_BASE_URL`      — base HTTPS URL of the shared HTTP API.
 *  - `MAZE_LEADERBOARD_PATH`  — the public leaderboard route ("/leaderboard").
 *  - `MAZE_HEALTH_PATH`       — the health route ("/health").
 *  - `MAZE_LEADERBOARD_QUERY` — a known, well-formed maze-parameter scope query string.
 *
 * The Synthetics "nodejs puppeteer" runtime provides `Synthetics` and `SyntheticsLogger`
 * as ambient modules; `executeHttpStep` records each request as a step with its own timing
 * and status, which is what surfaces the per-step latency the alarms evaluate.
 */
const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");

/** HTTP status the tokenless health probe must receive: the authorizer rejects it at 401. */
const HEALTH_EXPECTED_STATUS = 401;

/** Read a required canary environment variable, failing loudly if the wiring is missing. */
function requireEnv(name) {
  const value = process.env[name];
  if (value === undefined || value === "") {
    throw new Error(`missing required canary env var: ${name}`);
  }
  return value;
}

/** Parse "https://host/path" into the { hostname, port, path, protocol } request options. */
function toRequestOptions(url, method) {
  const parsed = new URL(url);
  return {
    hostname: parsed.hostname,
    method,
    path: `${parsed.pathname}${parsed.search}`,
    port: parsed.port === "" ? 443 : Number(parsed.port),
    protocol: parsed.protocol,
  };
}

const readonlyProbe = async function () {
  const baseUrl = requireEnv("MAZE_API_BASE_URL").replace(/\/+$/, "");
  const leaderboardPath = requireEnv("MAZE_LEADERBOARD_PATH");
  const healthPath = requireEnv("MAZE_HEALTH_PATH");
  const leaderboardQuery = requireEnv("MAZE_LEADERBOARD_QUERY");

  // Step 1 — public leaderboard: primary availability + latency signal. 200 + well-formed
  // body. This step's timing is the leaderboard p95 latency the alarm evaluates (R6.4).
  const leaderboardUrl = `${baseUrl}${leaderboardPath}${leaderboardQuery}`;
  await synthetics.executeHttpStep(
    "leaderboard-200",
    toRequestOptions(leaderboardUrl, "GET"),
    async function (res) {
      if (res.statusCode !== 200) {
        throw new Error(`leaderboard expected 200, got ${res.statusCode}`);
      }
      // Drain and validate the body shape: a well-formed leaderboard read has a
      // `standings` array. A 200 with a broken body is still a failure.
      let body = "";
      res.on("data", (chunk) => {
        body += chunk;
      });
      await new Promise((resolve, reject) => {
        res.on("end", () => {
          try {
            const parsed = JSON.parse(body);
            if (!Array.isArray(parsed.standings)) {
              reject(new Error("leaderboard body missing standings[]"));
              return;
            }
            log.info(`leaderboard ok: ${parsed.standings.length} standings`);
            resolve();
          } catch (err) {
            reject(new Error(`leaderboard body not JSON: ${String(err)}`));
          }
        });
        res.on("error", reject);
      });
    },
  );

  // Step 2 — health liveness: JWT-protected, so a tokenless probe must be rejected 401 at
  // the edge. That proves the API is reachable and the authorizer is live; a 5xx or a
  // network error means the edge is down and fails the run. No token is used here.
  const healthUrl = `${baseUrl}${healthPath}`;
  await synthetics.executeHttpStep(
    "health-liveness-401",
    toRequestOptions(healthUrl, "GET"),
    async function (res) {
      if (res.statusCode !== HEALTH_EXPECTED_STATUS) {
        throw new Error(
          `health liveness expected ${HEALTH_EXPECTED_STATUS} (tokenless), got ${res.statusCode}`,
        );
      }
      log.info("health liveness ok: authorizer rejected tokenless probe as expected");
    },
  );
};

exports.handler = async function () {
  return await readonlyProbe();
};
